generator.mjs.text:
// Deterministic sponsorship-media-kit builder: turns a content creator's own
// numbers (platforms, follower/engagement stats, audience breakdown, past
// brand work, a rate card) into (a) a self-contained, downloadable HTML
// one-sheet and (b) a plain-text version for pasting into an email or a
// brand's intake form. No network call lives here -- this module only turns
// structured input into text, so the identical logic runs from the browser
// form and from the test suite.
//
// Why a generator rather than a checker or a calculator: a creator's actual
// blocker when a brand asks "send your media kit" is not pricing math or a
// compliance verdict, it is producing a professional-looking one-pager at
// all, today, without paying for a template or a subscription tool that
// gates the export. Every field below maps to what a brand's own intake form
// or influencer-marketing platform actually asks for -- reach per platform,
// audience demographics, past collaborations, and a rate card -- so a brand
// can evaluate and pay a fair, self-stated rate without a back-and-forth
// email establishing it from scratch.

/** Escapes text for safe interpolation into the generated HTML document. */
export function escapeHtml(value) {
  return String(value ?? "").replace(/[&<>"']/g, (c) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
  }[c]));
}

/**
 * Parses a textarea's pipe-delimited lines into objects, positionally
 * matching `fields`. Blank lines and lines starting with "#" are skipped, so
 * a saved worked example can carry comments. Every value is trimmed; a line
 * with fewer segments than `fields` still parses, leaving the missing ones
 * `undefined` (later fields are frequently optional -- a collaboration with
 * no link, a platform stat with no engagement rate yet).
 *
 * @param {string} text
 * @param {string[]} fields
 * @returns {Record<string, string>[]}
 */
export function parsePipeList(text, fields) {
  const lines = String(text ?? "").split(/\r?\n/);
  const rows = [];
  for (const raw of lines) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) continue;
    const parts = line.split("|").map((p) => p.trim());
    if (!parts[0]) continue;
    const row = {};
    fields.forEach((field, i) => {
      const value = parts[i];
      if (value) row[field] = value;
    });
    rows.push(row);
  }
  return rows;
}

/**
 * How an engagement figure reads in the kit.
 *
 * The templates used to append " engagement" unconditionally, which is right
 * for the bare number the placeholder shows ("4.2%" -> "4.2% engagement") and
 * wrong the moment a creator names the metric themselves. A newsletter
 * operator typing "42% open", or anyone typing "3.2% CTR", got "42% open
 * engagement" in the file they send to a brand. So the word is added only when
 * the value is a bare number or percentage and says nothing about what it
 * measures.
 */
export function engagementLabel(value) {
  const text = String(value ?? "").trim();
  if (!text) return "";
  return /^[\d.,]+\s*%?$/.test(text) ? `${text} engagement` : text;
}

export const parsePlatforms = (text) => parsePipeList(text, ["platform", "followers", "engagement", "url"]);
export const parseAudience = (text) => parsePipeList(text, ["label", "value"]);
export const parseCollabs = (text) => parsePipeList(text, ["brand", "campaign", "url"]);
export const parseTestimonials = (text) => parsePipeList(text, ["quote", "source"]);
export const parseRates = (text) => parsePipeList(text, ["service", "price"]);

/**
 * Structural + completeness check, never a judgement of the creator's own
 * numbers -- this does not verify a follower count or an engagement rate
 * against any platform, it only checks the kit has what a brand's intake
 * form expects to find. Errors block generation (nothing to build without a
 * name and a bio); warnings describe a kit that will build but is missing
 * something a brand would look for before paying.
 * @param {object} data
 */
export function validateMediaKit(data) {
  const errors = [];
  const warnings = [];
  if (!String(data?.creatorName ?? "").trim()) errors.push("Creator or channel name is required.");
  if (!String(data?.bio ?? "").trim()) errors.push("A bio is required — it's the one thing every media kit needs.");

  if (!String(data?.contactEmail ?? "").trim()) {
    warnings.push("No partnerships contact email — add one so a brand can actually reach you.");
  }
  const platforms = parsePlatforms(data?.platformsRaw);
  if (platforms.length === 0) {
    warnings.push("No platforms listed — a brand reading this has no reach numbers to evaluate.");
  }
  const rates = parseRates(data?.ratesRaw);
  if (rates.length === 0) {
    warnings.push("No rate card — without one, a brand still won't know what to offer, and the back-and-forth this kit exists to skip starts anyway.");
  }
  if (!String(data?.photoUrl ?? "").trim()) {
    warnings.push("No photo link — most brands expect at least one creator or content photo.");
  }
  return { valid: errors.length === 0, errors, warnings };
}

const escLines = (text) => escapeHtml(text).split(/\r?\n\r?\n+/).map((p) => p.trim()).filter(Boolean);

/**
 * Builds a complete, self-contained HTML document: inline CSS, no external
 * script or stylesheet, print-friendly (`@media print`), and safe against
 * anything typed into the form (every interpolation is escaped). The only
 * external reference the output can contain is a photo URL the creator
 * themselves supplied -- nothing is uploaded or embedded from elsewhere.
 * @param {object} data
 * @returns {string}
 */
export function buildMediaKitHtml(data) {
  const name = String(data?.creatorName ?? "").trim();
  const tagline = String(data?.tagline ?? "").trim();
  const niche = String(data?.niche ?? "").trim();
  const location = String(data?.location ?? "").trim();
  const bioParas = escLines(data?.bio);
  const photoUrl = String(data?.photoUrl ?? "").trim();
  const photoAlt = String(data?.photoAlt ?? "").trim() || name;
  const contactName = String(data?.contactName ?? "").trim();
  const contactEmail = String(data?.contactEmail ?? "").trim();
  const contactPhone = String(data?.contactPhone ?? "").trim();
  const websiteUrl = String(data?.websiteUrl ?? "").trim();
  const platforms = parsePlatforms(data?.platformsRaw);
  const audience = parseAudience(data?.audienceRaw);
  const collabs = parseCollabs(data?.collabsRaw);
  const testimonials = parseTestimonials(data?.testimonialsRaw);
  const rates = parseRates(data?.ratesRaw);
  const generatedOn = data?.generatedOn instanceof Date
    ? data.generatedOn
    : new Date(data?.generatedOn ?? Date.now());
  const generatedLabel = Number.isNaN(generatedOn.getTime())
    ? ""
    : generatedOn.toISOString().slice(0, 10);

  const subline = [niche, location].filter(Boolean).map(escapeHtml).join(" &middot; ");

  const platformsBlock = platforms.length ? `
  <section>
    <h2>Reach</h2>
    <table class="stats">
      <tbody>
        ${platforms.map((p) => `<tr>
          <td class="k">${p.url ? `<a href="${escapeHtml(p.url)}" rel="noopener">${escapeHtml(p.platform || "")}</a>` : escapeHtml(p.platform || "")}</td>
          <td>${escapeHtml(p.followers || "")}</td>
          <td>${escapeHtml(engagementLabel(p.engagement))}</td>
        </tr>`).join("")}
      </tbody>
    </table>
  </section>` : "";

  const audienceBlock = audience.length ? `
  <section>
    <h2>Audience</h2>
    <ul class="stat-list">
      ${audience.map((a) => `<li><strong>${escapeHtml(a.value || "")}</strong> ${escapeHtml(a.label || "")}</li>`).join("")}
    </ul>
  </section>` : "";

  const collabsBlock = collabs.length ? `
  <section>
    <h2>Past partnerships</h2>
    <table class="stats">
      <tbody>
        ${collabs.map((c) => `<tr>
          <td class="k">${escapeHtml(c.brand || "")}</td>
          <td>${escapeHtml(c.campaign || "")}</td>
          <td>${c.url ? `<a href="${escapeHtml(c.url)}" rel="noopener">View</a>` : ""}</td>
        </tr>`).join("")}
      </tbody>
    </table>
  </section>` : "";

  const testimonialsBlock = testimonials.length ? `
  <section>
    <h2>What brands say</h2>
    ${testimonials.map((t) => `<blockquote>&ldquo;${escapeHtml(t.quote || "")}&rdquo;${t.source ? `<cite>&mdash; ${escapeHtml(t.source)}</cite>` : ""}</blockquote>`).join("")}
  </section>` : "";

  const ratesBlock = rates.length ? `
  <section>
    <h2>Rate card</h2>
    <table class="stats">
      <tbody>
        ${rates.map((r) => `<tr>
          <td class="k">${escapeHtml(r.service || "")}</td>
          <td>${escapeHtml(r.price || "")}</td>
        </tr>`).join("")}
      </tbody>
    </table>
    <p class="note">Starting rates — final pricing depends on usage rights, exclusivity, and turnaround.</p>
  </section>` : "";

  const contactLines = [
    contactName ? escapeHtml(contactName) : "",
    contactEmail ? `<a href="mailto:${escapeHtml(contactEmail)}">${escapeHtml(contactEmail)}</a>` : "",
    contactPhone ? escapeHtml(contactPhone) : "",
    websiteUrl ? `<a href="${escapeHtml(websiteUrl)}" rel="noopener">${escapeHtml(websiteUrl)}</a>` : "",
  ].filter(Boolean);

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escapeHtml(name)} — Media Kit${tagline ? ` — ${escapeHtml(tagline)}` : ""}</title>
<meta name="description" content="${escapeHtml(tagline || `Sponsorship media kit for ${name}`)}">
<style>
  :root { font: 16px/1.55 system-ui, -apple-system, "Segoe UI", sans-serif; color: #1b1f2a; background: #f2f4f7; }
  body { max-width: 760px; margin: auto; padding: 32px 24px 48px; }
  header { display: flex; gap: 22px; align-items: center; flex-wrap: wrap; margin-bottom: 22px; }
  header img { width: 168px; height: 168px; object-fit: cover; border-radius: 14px; background: #d5dbe3; }
  h1 { font-size: clamp(1.8rem, 5vw, 2.6rem); margin: 0 0 4px; line-height: 1.08; }
  .tagline { font-size: 1.05rem; color: #3a4658; margin: 0 0 4px; }
  .subline { color: #4c5a68; font-size: .92rem; margin: 0; text-transform: uppercase; letter-spacing: .04em; }
  h2 { font-size: 1.05rem; text-transform: uppercase; letter-spacing: .04em; color: #17324a; border-bottom: 2px solid #d5dbe3; padding-bottom: 6px; margin: 30px 0 12px; }
  section p { margin: 0 0 12px; }
  ul.stat-list { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 10px 22px; }
  ul.stat-list li { font-size: .94rem; }
  ul.stat-list li strong { color: #17324a; margin-right: 4px; }
  table.stats { width: 100%; border-collapse: collapse; }
  table.stats td { padding: 7px 6px; border-bottom: 1px solid #e3e9ef; font-size: .94rem; vertical-align: top; }
  table.stats td.k { font-weight: 600; white-space: nowrap; padding-right: 14px; }
  table.stats a { color: #17604a; font-weight: 600; text-decoration: none; }
  table.stats a:hover { text-decoration: underline; }
  blockquote { margin: 0 0 14px; padding-left: 14px; border-left: 3px solid #d5dbe3; font-style: italic; }
  blockquote cite { display: block; font-style: normal; font-size: .86rem; color: #4c5a68; margin-top: 4px; }
  .contact { display: flex; flex-wrap: wrap; gap: 4px 18px; }
  footer { margin-top: 34px; padding-top: 14px; border-top: 1px solid #d5dbe3; font-size: .78rem; color: #4c5a68; }
  footer a { color: #4c5a68; }
  .note { color: #4c5a68; font-size: .9rem; }
  @media print {
    body { background: #fff; max-width: none; padding: 0 8mm; }
    header img { width: 130px; height: 130px; }
    footer { display: none; }
  }
</style>
</head>
<body>
  <header>
    ${photoUrl ? `<img src="${escapeHtml(photoUrl)}" alt="${escapeHtml(photoAlt)}">` : ""}
    <div>
      <h1>${escapeHtml(name)}</h1>
      ${tagline ? `<p class="tagline">${escapeHtml(tagline)}</p>` : ""}
      ${subline ? `<p class="subline">${subline}</p>` : ""}
    </div>
  </header>

  <section>
    <h2>About</h2>
    ${bioParas.map((p) => `<p>${p}</p>`).join("")}
  </section>
  ${platformsBlock}
  ${audienceBlock}
  ${collabsBlock}
  ${testimonialsBlock}
  ${ratesBlock}

  <section>
    <h2>Contact</h2>
    <p class="contact">${contactLines.join(" &nbsp;&middot;&nbsp; ") || "&mdash;"}</p>
  </section>

  <footer>
    <p>Media kit${generatedLabel ? ` generated ${generatedLabel}` : ""}. Built with the free, no-signup <a href="https://duncan-haywood.github.io/monorepo-projects/influencer-media-kit-generator/" rel="noopener">Media Kit Generator</a> — nothing in it was uploaded to build this page; it runs entirely in the browser that made it.</p>
  </footer>
</body>
</html>
`;
}

/**
 * The same content as `buildMediaKitHtml`, as plain text for pasting into an
 * email body or a brand's intake form where HTML isn't accepted.
 * @param {object} data
 * @returns {string}
 */
export function buildOneSheetText(data) {
  const name = String(data?.creatorName ?? "").trim();
  const tagline = String(data?.tagline ?? "").trim();
  const niche = String(data?.niche ?? "").trim();
  const location = String(data?.location ?? "").trim();
  const bio = String(data?.bio ?? "").trim();
  const contactName = String(data?.contactName ?? "").trim();
  const contactEmail = String(data?.contactEmail ?? "").trim();
  const contactPhone = String(data?.contactPhone ?? "").trim();
  const websiteUrl = String(data?.websiteUrl ?? "").trim();
  const platforms = parsePlatforms(data?.platformsRaw);
  const audience = parseAudience(data?.audienceRaw);
  const collabs = parseCollabs(data?.collabsRaw);
  const testimonials = parseTestimonials(data?.testimonialsRaw);
  const rates = parseRates(data?.ratesRaw);

  const lines = [];
  lines.push(name || "(no creator name)");
  const subline = [niche, location].filter(Boolean).join(" | ");
  if (tagline) lines.push(tagline);
  if (subline) lines.push(subline);
  lines.push("");
  if (bio) { lines.push("ABOUT", bio, ""); }

  if (platforms.length) {
    lines.push("REACH");
    for (const p of platforms) {
      const bits = [p.followers, engagementLabel(p.engagement)].filter(Boolean).join(", ");
      lines.push(`- ${p.platform || ""}${bits ? `: ${bits}` : ""}${p.url ? ` (${p.url})` : ""}`);
    }
    lines.push("");
  }
  if (audience.length) {
    lines.push("AUDIENCE");
    for (const a of audience) lines.push(`- ${a.value || ""} ${a.label || ""}`);
    lines.push("");
  }
  if (collabs.length) {
    lines.push("PAST PARTNERSHIPS");
    for (const c of collabs) {
      lines.push(`- ${[c.brand, c.campaign].filter(Boolean).join(" — ")}${c.url ? ` (${c.url})` : ""}`);
    }
    lines.push("");
  }
  if (testimonials.length) {
    lines.push("WHAT BRANDS SAY");
    for (const t of testimonials) lines.push(`- "${t.quote || ""}"${t.source ? ` — ${t.source}` : ""}`);
    lines.push("");
  }
  if (rates.length) {
    lines.push("RATE CARD");
    for (const r of rates) lines.push(`- ${r.service || ""}: ${r.price || ""}`);
    lines.push("(Starting rates — final pricing depends on usage rights, exclusivity, and turnaround.)");
    lines.push("");
  }

  const contactLine = [contactName, contactEmail, contactPhone, websiteUrl].filter(Boolean).join(" | ");
  if (contactLine) lines.push("CONTACT", contactLine);

  return lines.join("\n").replace(/\n{3,}/g, "\n\n").trim() + "\n";
}

prefill.mjs.text:
// Accept a platform line and a rate card handed over from another tool.
//
// `ventures/brand-deal-rate-calculator` computes exactly the two things
// `validateMediaKit` warns about when they are missing -- a platform-stats
// line and a rate card -- and until now a creator who had just seen those
// numbers had to retype all of them here. Its `handoff.mjs` builds a relative
// link carrying them in the URL fragment; this module is the receiving half.
//
// Three rules shape it, and each is a bug it is written to not have:
//
// 1. **It never overwrites.** A creator can arrive here with a saved draft
//    they have spent twenty minutes on. Silently replacing a rate card with
//    an incoming one would destroy work with no error and no undo, so
//    `mergeLines` only ever *appends* lines that are not already present, and
//    the page asks before it does even that.
//
// 2. **It trusts nothing in the URL.** A fragment is whatever was in the link
//    someone clicked. Only the form's own field names are read (checked
//    against `STRING_FIELDS`, imported rather than restated), every value is
//    stripped of control characters, and both the line count and the total
//    length are capped -- so a hostile or malformed link cannot wedge the
//    form or fill localStorage. The values land in a textarea's `value` and
//    are escaped again by `generator.mjs` on render, so this is defence in
//    depth rather than the only guard.
//
// 3. **Nothing is transmitted.** The values ride in the fragment, which
//    browsers do not send to any server, and this module does no I/O at all.
//    `storage` and the location string are both passed in, so this stays
//    testable without a DOM.

import { STRING_FIELDS } from "./state.mjs";

/** The fields a handoff link is allowed to fill. */
export const PREFILLABLE = Object.freeze(["platformsRaw", "ratesRaw"]);

/** Caps. Generous for a real rate card, far below anything that could wedge
 * the form or exhaust storage. */
export const LIMITS = Object.freeze({ maxLines: 24, maxLineLength: 200, maxFieldLength: 4000 });

/**
 * Strips control characters (including the newlines that would forge extra
 * rows inside a single one) and collapses runs of whitespace, then trims.
 */
function cleanLine(line) {
  return String(line ?? "")
    // Control characters (the newlines among them would forge extra rows
    // inside a single one), plus the Unicode bidi and zero-width formatting
    // characters that can make a price read as a different number than it is.
    .replace(/[\u0000-\u001F\u007F-\u009F\u200B-\u200F\u202A-\u202E\u2066-\u2069\uFEFF]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, LIMITS.maxLineLength);
}

/**
 * Normalises one incoming field to at most `maxLines` clean, non-empty lines.
 * Returns "" when nothing survives, so a caller can treat empty as absent.
 */
export function cleanBlock(value) {
  const lines = String(value ?? "")
    .split(/\r?\n/)
    .map(cleanLine)
    .filter(Boolean)
    .slice(0, LIMITS.maxLines);
  return lines.join("\n").slice(0, LIMITS.maxFieldLength);
}

/**
 * Reads a handoff out of a location fragment or query string.
 *
 * @param {string} value `location.hash` or `location.search`, with or without
 *   its leading `#`/`?`.
 * @returns {{platformsRaw?: string, ratesRaw?: string}|null} null when the
 *   link carries no usable handoff at all.
 */
export function readHandoff(value) {
  const raw = String(value ?? "").replace(/^[#?]/, "");
  if (!raw) return null;
  let params;
  try {
    params = new URLSearchParams(raw);
  } catch {
    return null;
  }
  const out = {};
  for (const field of PREFILLABLE) {
    // A field this module thinks is prefillable but the form does not have
    // would fill nothing. Caught by a test rather than left to be noticed in
    // production, but checked here too so a stale constant cannot half-work.
    if (!STRING_FIELDS.includes(field)) continue;
    const cleaned = cleanBlock(params.get(field));
    if (cleaned) out[field] = cleaned;
  }
  return Object.keys(out).length > 0 ? out : null;
}

/**
 * Appends the lines of `incoming` that `current` does not already have.
 *
 * Append rather than replace: see rule 1 above. Duplicate detection compares
 * whole trimmed lines, so a creator who follows the same handoff link twice
 * gets one rate card rather than two, while a genuinely different price for
 * the same deliverable is kept -- this module has no business deciding which
 * of two prices for "Instagram feed post" the creator meant.
 *
 * @returns {{text: string, added: number}}
 */
export function mergeLines(current, incoming) {
  const existing = String(current ?? "").split(/\r?\n/);
  const seen = new Set(existing.map((line) => line.trim()).filter(Boolean));
  const additions = [];
  for (const line of String(incoming ?? "").split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || seen.has(trimmed)) continue;
    seen.add(trimmed);
    additions.push(trimmed);
  }
  if (additions.length === 0) return { text: String(current ?? ""), added: 0 };
  const base = String(current ?? "").replace(/\s+$/, "");
  const text = base ? `${base}\n${additions.join("\n")}` : additions.join("\n");
  return { text, added: additions.length };
}

/**
 * Applies a handoff to the current form values, without destroying any of
 * them.
 *
 * @param {object} current the form's `{platformsRaw, ratesRaw, ...}`
 * @param {object} handoff the result of `readHandoff`
 * @returns {{values: object, added: Record<string, number>, total: number}}
 */
export function applyHandoff(current = {}, handoff = null) {
  const values = { ...current };
  const added = {};
  let total = 0;
  if (!handoff) return { values, added, total };
  for (const field of PREFILLABLE) {
    const incoming = handoff[field];
    if (!incoming) continue;
    const merged = mergeLines(current?.[field], incoming);
    values[field] = merged.text;
    added[field] = merged.added;
    total += merged.added;
  }
  return { values, added, total };
}

/**
 * One sentence naming what a link is offering, for the banner that asks
 * before inserting anything. Counts rows rather than characters because that
 * is what the reader will see appear in the two boxes.
 */
export function describeHandoff(handoff) {
  if (!handoff) return "";
  const countLines = (value) => (value ? value.split("\n").filter(Boolean).length : 0);
  const parts = [];
  const platforms = countLines(handoff.platformsRaw);
  const rates = countLines(handoff.ratesRaw);
  if (platforms) parts.push(`${platforms} platform ${platforms === 1 ? "row" : "rows"}`);
  if (rates) parts.push(`${rates} rate-card ${rates === 1 ? "row" : "rows"}`);
  return parts.join(" and ");
}

state.mjs.text:
// Autosaves the form to the visitor's own browser so a media kit with a
// dozen fields (bio, platform stats, audience breakdown, past partnerships, a
// rate card) survives a closed tab -- the same problem the fleet's trade
// calculators solve with `share.mjs`, but that module's shape (a fixed spec
// of short numbers/flags, a 512-char cap per text field) does not fit this
// venture's data: a bio is routinely several paragraphs, and the
// platform/audience/collab/rate lists are open-ended text blocks, not named
// numeric ids. Sharing the *builder* via a URL link (that module's other
// job) also does not apply here the way it does for a bid -- the deliverable
// a creator sends onward is the generated file itself (downloaded or
// copied), not a link back into this form. So this is a small, purpose-built
// equivalent: one JSON blob, one localStorage key, re-validated shape on
// read so a corrupted or foreign value can't wedge the form. Same shape as
// epk-generator/state.mjs, the closest sibling venture.
//
// Nothing here is transmitted anywhere. `storage` is passed in rather than
// read from a global so this stays testable without a DOM.

const KEY = "influencer-media-kit-generator-draft";
const VERSION = 1;

// Exported so `prefill.mjs` can check an incoming link's field names against
// the form's real ones rather than restating the list. A field renamed here
// then fails that module's test instead of silently accepting a link that
// fills nothing.
export const STRING_FIELDS = Object.freeze([
  "creatorName", "tagline", "niche", "location", "bio",
  "photoUrl", "photoAlt",
  "contactName", "contactEmail", "contactPhone", "websiteUrl",
  "platformsRaw", "audienceRaw", "collabsRaw", "testimonialsRaw", "ratesRaw",
]);

/** Keeps only known string fields, so a foreign or corrupted blob can't leak
 * arbitrary keys into the form. */
function sanitize(data) {
  const out = {};
  for (const field of STRING_FIELDS) {
    const value = data?.[field];
    if (typeof value === "string" && value.length) out[field] = value;
  }
  return out;
}

/** @param {Storage|null} storage @param {object} data @returns {boolean} */
export function saveDraft(storage, data) {
  if (!storage) return false;
  try {
    const clean = sanitize(data);
    if (Object.keys(clean).length === 0) {
      storage.removeItem(KEY);
      return true;
    }
    storage.setItem(KEY, JSON.stringify({ v: VERSION, data: clean }));
    return true;
  } catch {
    return false;
  }
}

/** @param {Storage|null} storage @returns {object} */
export function loadDraft(storage) {
  if (!storage) return {};
  try {
    const raw = storage.getItem(KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
